package com.northstar.crm.ui;

import com.northstar.crm.service.AccountService;import com.vaadin.flow.component.*;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.login.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.router.*;import com.vaadin.flow.server.auth.AnonymousAllowed;
@Route("login") @PageTitle("Sign in · Northstar") @AnonymousAllowed public class LoginView extends VerticalLayout implements BeforeEnterObserver {
 private final LoginForm form=new LoginForm();
 public LoginView(AccountService accounts){addClassName("login-view");setSizeFull();var mark=new Div("N");mark.addClassName("login-mark");var intro=new VerticalLayout(mark,new Span("NORTHSTAR / CUSTOMER OPERATIONS"),new H1("Keep every customer promise in view."),new Paragraph("Renewals, support, access and customer context—one accountable workspace."));intro.addClassName("login-intro");var card=new VerticalLayout(new H2("Welcome back"),new Paragraph("Use your company credentials to continue."),form,new Anchor("/partner/console","Partner console"));form.setAction("login");form.setForgotPasswordButtonVisible(true);form.addForgotPasswordListener(e->forgot(accounts));card.addClassName("login-card");var shell=new HorizontalLayout(intro,card);shell.addClassName("login-shell");shell.setWidthFull();shell.setAlignItems(Alignment.CENTER);add(shell);setJustifyContentMode(JustifyContentMode.CENTER);setAlignItems(Alignment.CENTER);}
 private void forgot(AccountService accounts){var email=new EmailField("Work email");email.setWidthFull();var dialog=new com.vaadin.flow.component.dialog.Dialog();dialog.setHeaderTitle("Reset your password");dialog.add(new Paragraph("We’ll write a single-use, one-hour reset link to the local email outbox."),email);dialog.getFooter().add(new Button("Cancel",e->dialog.close()),UiKit.primary("Send reset link",e->{try{accounts.requestPasswordReset(email.getValue());dialog.close();UiKit.success("A reset link was written to the email outbox");}catch(Exception ex){UiKit.error(ex);}}));dialog.open();}
 @Override public void beforeEnter(BeforeEnterEvent e){if(e.getLocation().getQueryParameters().getParameters().containsKey("error"))form.setError(true);}
}
